const body = $('Webhook').item.json.body;
const searchType = body.search_type;
const query = body.query;
const country = body.country_code || 'ALL';
const mediaType = body.media_type || 'all';

let url;
if (searchType === 'keyword') {
  const encoded = encodeURIComponent(query);
  url = `https://www.facebook.com/ads/library/?active_status=active&ad_type=all&country=${country}&media_type=${mediaType}&q=${encoded}&search_type=keyword_unordered`;
} else {
  url = query.startsWith('http') ? query : `https://www.facebook.com/${query}`;
}

return [{
  json: {
    url,
    max_ads: body.max_ads || 50,
    search_id: body.search_id,
    supabase_url: body.supabase_url,
    supabase_service_key: body.supabase_service_key
  }
}];

// Filter ads and extract key fields — MIN 3 days active
const items = $input.all();
const ctx = $('Build Apify URL').first().json;
const now = new Date();
const MIN_DAYS = 3;

// Check if Apify returned an error
const first = items[0]?.json || {};
if (first.error || first.statusCode >= 400 || first.message) {
  return [{
    json: {
      _no_results: true,
      _error: true,
      _error_message: first.error || first.message || 'Apify returned error status ' + (first.statusCode || 'unknown'),
      _search_id: ctx.search_id,
      _supabase_url: ctx.supabase_url,
      _supabase_service_key: ctx.supabase_service_key,
      _total_count: 0,
      _filtered_count: 0
    }
  }];
}

const filtered = [];
let totalCount = items.length;
let skippedNoDate = 0;
let skippedTooNew = 0;

for (const item of items) {
  const ad = item.json;

  const startDateStr = ad.startDate || ad.start_date || ad.startDateFormatted || ad.start_date_formatted;
  if (!startDateStr) { skippedNoDate++; continue; }

  const startDate = new Date(startDateStr);
  if (isNaN(startDate.getTime())) { skippedNoDate++; continue; }

  const daysActive = Math.floor((now.getTime() - startDate.getTime()) / (1000 * 60 * 60 * 24));
  if (daysActive < MIN_DAYS) { skippedTooNew++; continue; }

  const snapshot = ad.snapshot || {};
  const hasVideo = snapshot.videos && snapshot.videos.length > 0 && snapshot.videos[0].video_sd_url;
  const hasImage = snapshot.images && snapshot.images.length > 0 && snapshot.images[0].original_image_url;
  const adType = hasVideo ? 'video' : hasImage ? 'image' : 'text';

  let mediaUrl = null;
  if (hasVideo) mediaUrl = snapshot.videos[0].video_sd_url;
  else if (hasImage) mediaUrl = snapshot.images[0].original_image_url;

  filtered.push({
    json: {
      ad_archive_id: String(ad.adArchiveID || ad.ad_archive_id || ad.id || ''),
      page_id: String(ad.pageID || ad.page_id || ''),
      page_name: ad.pageName || ad.page_name || 'Unknown',
      page_url: ad.pageAlias ? `https://facebook.com/${ad.pageAlias}` : null,
      page_likes: ad.pageLikes || ad.page_likes || null,
      ad_start_date: startDate.toISOString().split('T')[0],
      days_active: daysActive,
      ad_type: adType,
      original_ad_copy: snapshot.body?.text || ad.ad_creative_bodies?.[0] || ad.body || null,
      media_url: mediaUrl,
      raw_data: ad,
      _search_id: ctx.search_id,
      _supabase_url: ctx.supabase_url,
      _supabase_service_key: ctx.supabase_service_key,
      _total_count: totalCount
    }
  });
}

console.log(`Apify returned ${totalCount} items. Skipped: ${skippedNoDate} no date, ${skippedTooNew} too new (<${MIN_DAYS}d). Passed: ${filtered.length}`);

if (filtered.length === 0) {
  return [{
    json: {
      _no_results: true,
      _search_id: ctx.search_id,
      _supabase_url: ctx.supabase_url,
      _supabase_service_key: ctx.supabase_service_key,
      _total_count: totalCount,
      _filtered_count: 0
    }
  }];
}

// Sort by days_active desc so best ads come first
filtered.sort((a, b) => b.json.days_active - a.json.days_active);
filtered[0].json._filtered_count = filtered.length;

return filtered;

