const ad = $('Loop Ads').item.json;

let mediaDescription = null;

try {
  const geminiRes = $input.first().json;
  if (geminiRes.candidates && geminiRes.candidates[0]) {
    mediaDescription = geminiRes.candidates[0].content?.parts?.[0]?.text || null;
  }
} catch(e) {}

return [{
  json: {
    ...ad,
    media_description: mediaDescription
  }
}];

