const ad = $('Merge Media Desc').item.json;
let summary = null;

try {
  const res = $input.first().json;
  const text = res.content?.[0]?.text || '';
  const match = text.match(/\{[\s\S]*\}/);
  if (match) {
    const parsed = JSON.parse(match[0]);
    summary = parsed.summary || null;
  } else {
    summary = text;
  }
} catch(e) {}

return [{
  json: {
    ...ad,
    summary
  }
}];

