const ad = $('Extract Summary').item.json;
let rewrittenCopy = null;

try {
  const res = $input.first().json;
  const text = res.content?.[0]?.text || '';
  const match = text.match(/\{[\s\S]*\}/);
  if (match) {
    const parsed = JSON.parse(match[0]);
    rewrittenCopy = parsed.rewrittenAdCopy || parsed.rewritten_ad_copy || null;
  } else {
    rewrittenCopy = text;
  }
} catch(e) {}

return [{
  json: {
    search_id: ad._search_id,
    ad_archive_id: ad.ad_archive_id,
    page_id: ad.page_id,
    page_name: ad.page_name,
    page_url: ad.page_url,
    page_likes: ad.page_likes,
    ad_start_date: ad.ad_start_date,
    days_active: ad.days_active,
    ad_type: ad.ad_type,
    original_ad_copy: ad.original_ad_copy,
    media_url: ad.media_url,
    media_description: ad.media_description,
    summary: ad.summary,
    rewritten_copy: rewrittenCopy,
    raw_data: ad.raw_data,
    _supabase_url: ad._supabase_url,
    _supabase_service_key: ad._supabase_service_key,
    _search_id: ad._search_id,
    _total_count: ad._total_count,
    _filtered_count: ad._filtered_count
  }
}];

const allItems = $('Prepare Save').all();
const first = allItems[0]?.json || {};

return [{
  json: {
    search_id: first._search_id,
    supabase_url: first._supabase_url,
    supabase_service_key: first._supabase_service_key,
    total_count: first._total_count || 0,
    filtered_count: first._filtered_count || allItems.length
  }
}];
